@f3 w.request.filler text=thanks
@r1 w.request.request act=ask mood=ask words="I want a list of orders above 5000 for the channel report" predicate=I question=list
@r1.t w.request.target request=$r1 family=chart mode=existing determiner=definite fill=description
@r1.l1 w.request.lookup request=$r1 target=$r1.t key=thing from=page

@r1 w.request.request act=change mood=do predicate=show
@r1.t w.request.target request=$r1 family=chart mode=existing determiner=definite fill=context family_words=chart description="variation chart"
@r1.l1 w.request.lookup request=$r1 target=$r1.t key=thing
@r1.c1 w.request.constraint request=$r1 on=attribute attribute=chart.show_values value=show words=printed operator=eq phase=result key_words=values

@r1 w.request.request act=make mood=do predicate=Plot
