@r1.c3 w.request.constraint request=$r1 on=attribute attribute=chart.yLabel value=revenue operator=eq phase=result
@r1.u1 w.request.unread request=$r1 text="axis titles" note=chart.brief
@r1.c4 w.request.constraint request=$r1 on=attribute attribute=chart.measure value=legend operator=eq phase=result
@r1.c5 w.request.constraint request=$r1 on=attribute attribute=chart.dimension value=campaign operator=eq phase=result key_words="per campaign"

@r1 w.request.request act=place mode=arrange mood=do predicate=can
@r1.t w.request.target request=$r1 family=diagram mode=existing determiner=definite fill=context family_words=diagram
@r1.l1 w.request.lookup request=$r1 target=$r1.t key=thing from=page
