@r1.c2 w.request.constraint request=$r1 on=attribute attribute=chart.dimension value=month operator=eq phase=result key_words="grouped by month"

@f1 w.request.filler text="get a chance"
@r1 w.request.request act=remove mood=do words="take away the two on the right" predicate=take
@r1.t w.request.target request=$r1 family=node mode=existing determiner=definite fill=context
@r1.l1 w.request.lookup request=$r1 target=$r1.t key=thing from=page
