@r1 w.request.request act=place mood=do words="move box three a single place right" predicate=move
@r1.t w.request.target request=$r1 family=node mode=existing determiner=definite fill=context family_words=box
@r1.l1 w.request.lookup request=$r1 target=$r1.t key=thing from=page
