@r2.u1 w.request.constraint request=$r2 on=attribute attribute=node.restore value=previous words="a single place left" operator=eq phase=result

@f1 w.request.filler text=wondering
@f2 w.request.filler text=please
@r1 w.request.request act=ask mood=ask words="can u trace the flow for a failed upload please" predicate=trace question=which
