@r1.l1 w.request.lookup request=$r1 target=$r1.t key=thing from=page
@r1.u1 w.request.unread request=$r1 text="trace the flow" note=diagram.step.index value="the flow"

@f1 w.request.filler text=no
@r1 w.request.request act=change mood=do predicate=need
@r1.t w.request.target request=$r1 family=chart mode=existing determiner=definite fill=context
@r1.l1 w.request.lookup request=$r1 target=$r1.t key=thing from=page
