@f1 w.request.filler text=please
@r1 w.request.request act=make mood=do words="give me a bar chart that counts the broadcasts per time of day" predicate=give
@r1.t w.request.target request=$r1 family=chart mode=new determiner=indefinite family_words=chart
@r1.c1 w.request.constraint request=$r1 on=attribute attribute=chart.type value=bar words="bar chart" operator=eq phase=result
@r1.c2 w.request.constraint request=$r1 on=attribute attribute=chart.dimension value="time of day" operator=eq phase=result key_words="per time of day"
@r1.c3 w.request.constraint request=$r1 on=attribute attribute=chart.measure value=broadcasts operator=eq phase=result
@r1.c4 w.request.constraint request=$r1 on=attribute attribute=chart.aggregate value=count operator=eq phase=result words=counts

@r1 w.request.request act=change mood=do predicate=put words="put harpoon heads on the Start arrow"
@r1.t w.request.target request=$r1 family=link mode=existing determiner=definite fill=description family_words=arrow
@r1.l1 w.request.lookup request=$r1 target=$r1.t key=thing from=page
