@r1.u1 w.request.unread request=$r1 text="harpoon heads" note=link.arrowTip value=harpoon
@r2 w.request.request act=change mood=do words="and give stealth tips to the Scan ones" predicate=give
@r2.t w.request.target request=$r2 family=link mode=existing determiner=definite fill=description
@r2.l1 w.request.lookup request=$r2 target=$r2.t key=thing from=page
